  // ---- ElevenLabs on the Uso page (2026-10-17) ----
  // Credits from ElevenLabs, the units of the chosen voice in Camino order,
  // and "Generar en orden": unit by unit, only what's missing, and only
  // when the credits left cover the whole unit (tags included).
  var elState = { loaded: false, status: null, vk: Object.keys(ELEVEN_VOICES)[0], run: null };
  // Credits per character through the API (2026-10-17). ElevenLabs:
  // "for generations made in the app (the web editor), credits are used at
  // 1 credit per character"; through the API v4 is billed by the
  // character at a rate that comes to ~275,000 characters for the plan
  // (≈ 0.44 credits each). voseá uses the API, so the real rate is measured
  // during "Generar" (credits used ÷ characters sent) and kept on this
  // device. Until it's measured, 1 credit per character (never short).
  var EL_RATE_KEY = "vosea-el-rate";
  function elRate() { try { var r = Number(localStorage.getItem(EL_RATE_KEY)); return r >= 0.05 && r <= 3 ? r : 0; } catch (e) { return 0; } }
  function elSetRate(r) { try { localStorage.setItem(EL_RATE_KEY, String(Math.round(r * 1000) / 1000)); } catch (e) {} }
  function elCredits(chars) { return Math.ceil(chars * (elRate() || 1)); }
  function elCall(body) {
    return supabaseClient.functions.invoke("tts", { body: body }).then(function (res) {
      if (res.error) {
        var ctx = res.error.context;
        return Promise.resolve(ctx && typeof ctx.json === "function" ? (ctx.clone ? ctx.clone().json() : ctx.json()) : null).catch(function () { return null; }).then(function (b) {
          var e = new Error((b && (b.detail ? b.error + ": " + b.detail : b.error)) || ("HTTP " + ((ctx && ctx.status) || "?")));
          e.code = b && b.error; e.status = ctx && ctx.status;
          throw e;
        });
      }
      if (!res.data) throw new Error("no_data");
      return res.data;
    });
  }
  function refreshEleven() {
    return Promise.all([elCall({ action: "eleven_status" }).catch(function (e) {
      // an older tts (before commit 100) doesn't know these actions
      return { configured: true, error: e.code === "unknown_action" ? t("el_old_fn") : e.message, old: e.code === "unknown_action" };
    }), loadElevenVoices()]).then(function (r) {
      elState.loaded = true; elState.status = r[0];
      renderEleven();
    });
  }
  function elDate(unix) {
    if (!unix) return "";
    return new Date(unix * 1000).toLocaleDateString(currentLang === "es" ? "es-AR" : "en-US", { day: "numeric", month: "short" });
  }
  // Generating stops at 90 % of the account's credits (mason, 2026-10-17:
  // "use 90% of the total credits (subscription + any purchased
  // credits)"), keeping the last 10 % for the web editor and retakes. The
  // total is ElevenLabs' own character_limit for this period, which
  // includes rollover and bought credits.
  var EL_CAP_PCT = 90;
  function elCap(st) { return st && st.limit ? Math.floor(st.limit * EL_CAP_PCT / 100) : 0; }
  function elLeftOf(st) { return st && st.limit ? Math.max(0, elCap(st) - (Number(st.used) || 0)) : 0; }
  function elLeft() { return elLeftOf(elState.status); }
  function renderEleven() {
    var box = el.usageEleven;
    if (!box) return;
    box.textContent = "";
    var sec = usageSection(t("el_title"));
    box.appendChild(sec);
    if (!elState.loaded) { sec.appendChild(uNode("p", "usage-note", t("el_loading"))); return; }
    var st = elState.status || {};
    if (st.configured === false) { sec.appendChild(uNode("p", "usage-note", t("el_off"))); return; }
    if (st.error) sec.appendChild(uNode("p", "usage-problem", st.old ? st.error : t("el_error", { msg: st.error })));
    else if (st.limit) {
      sec.appendChild(usageMeter(t("el_credits"), t("el_credits_of", { used: progNum(st.used), limit: progNum(st.limit) }), st.used, st.limit, { reservePct: EL_CAP_PCT }));
      sec.appendChild(uNode("p", "usage-note", t("el_left", { left: progNum(elLeft()), cap: progNum(elCap(st)), pct: EL_CAP_PCT, date: elDate(st.reset_unix) })));
      var rate = elRate();
      sec.appendChild(uNode("p", "usage-note el-rate", rate ? t("el_rate", { r: progNum(rate, 2) }) : t("el_rate_unknown")));
    }
    if (!elevenVoicesSql) sec.appendChild(uNode("p", "usage-problem", t("el_sql")));
    var vks = Object.keys(ELEVEN_VOICES), run = elState.run, busy = !!(run && run.running);
    if (vks.length > 1) {
      var vt = uNode("div", "lang-toggle el-voices");
      vks.forEach(function (vk) {
        var b = uNode("button", "lang-option" + (elState.vk === vk ? " active" : ""), ELEVEN_VOICES[vk].label);
        b.type = "button"; b.disabled = busy;
        b.addEventListener("click", function () { elState.vk = vk; renderEleven(); });
        vt.appendChild(b);
      });
      sec.appendChild(vt);
    } else sec.appendChild(uNode("p", "usage-note", t("el_voice") + ": " + ELEVEN_VOICES[elState.vk].label));
    var units = elevenUnits(elState.vk), list = uNode("ul", "el-units"), todo = 0, todoChars = 0;
    units.forEach(function (u) {
      var ready = !!elevenUnitsReady[u.vk + "|" + u.sc.id + "|" + u.role] && elevenUnitsReady[u.vk + "|" + u.sc.id + "|" + u.role] === u.sig;
      var li = uNode("li", "el-unit" + (ready ? " is-ready" : "") + (run && run.cur === u.sc.id + "|" + u.role ? " is-now" : ""));
      li.setAttribute("data-unit", u.sc.id + "|" + u.role);
      li.appendChild(uNode("span", "el-unit-n", elevenUnitName(u)));
      li.appendChild(uNode("span", "count", ready ? "✓ " + t("el_ready") : t("el_unit_cost", { n: progNum(u.texts.length), c: progNum(u.chars) })));
      li.title = t("el_unit_credits", { k: progNum(elCredits(u.chars)) });
      list.appendChild(li);
      if (!ready) { todo++; todoChars += u.chars; }
    });
    sec.appendChild(uNode("p", "usage-note el-todo", todo ? t("el_todo", { n: progNum(todo), c: progNum(todoChars), k: progNum(elCredits(todoChars)) }) : t("el_all_done")));
    var cc = clipCount.eleven[elState.vk];
    if (cc) sec.appendChild(uNode("p", "usage-note el-have", t("el_have", { voice: ELEVEN_VOICES[elState.vk].label, have: progNum(cc[0]), total: progNum(cc[1]) })));
    sec.appendChild(list);
    sec.appendChild(uNode("p", "usage-note", t("el_note")));
    // the narrated welcome (both languages, Valeria and Agustín in turns)
    var wu = welcomeUnits(), wTodo = 0, wChars = 0, wNames = [], wl = uNode("ul", "el-units el-welcome");
    wu.forEach(function (u) {
      var ready = elevenUnitsReady[u.vk + "|" + u.sc.id + "|n"] === u.sig;
      var li = uNode("li", "el-unit" + (ready ? " is-ready" : ""));
      li.setAttribute("data-unit", u.sc.id + "|" + u.vk);
      li.appendChild(uNode("span", "el-unit-n", u.name));
      li.appendChild(uNode("span", "count", ready ? "✓ " + t("el_ready") : t("el_unit_cost", { n: progNum(u.texts.length), c: progNum(u.chars) })));
      wl.appendChild(li);
      if (!ready) { wTodo++; wChars += u.chars; wNames.push(u.name); }
    });
    sec.appendChild(uNode("h5", "el-sub", t("el_welcome_title")));
    sec.appendChild(wl);
    if (wTodo) {
      var wgo = uNode("button", "btn-secondary", t("el_welcome_go", { k: progNum(elCredits(wChars)) }));
      wgo.type = "button"; wgo.id = "el-welcome-go";
      wgo.disabled = busy || !st.limit || !!st.error || !elevenVoicesSql;
      wgo.addEventListener("click", function () {
        if (!window.confirm(t("el_welcome_confirm", { what: wNames.join(", "), k: progNum(elCredits(wChars)) }))) return;
        elevenRun(welcomeUnits(), { reserve: true });
      });
      var wa = uNode("div", "form-actions"); wa.appendChild(wgo); sec.appendChild(wa);
    }
    var actions = uNode("div", "form-actions");
    var go = uNode("button", "btn-primary", busy ? t("el_stop") : t("el_go"));
    go.type = "button"; go.id = "el-go";
    go.disabled = !busy && (!todo || !st.limit || !!st.error || !elevenVoicesSql);
    go.addEventListener("click", function () { if (busy) { elState.run.stop = true; go.disabled = true; } else elevenRun(); });
    actions.appendChild(go);
    sec.appendChild(actions);
    if (run && run.msg) sec.appendChild(uNode("p", run.bad ? "usage-problem" : "warm-progress", run.msg));
  }
  // queue: the units to make (default: the chosen voice's scene roles);
  // opts.reserve: may use the last 10 % (the narrated welcome, asked for
  // explicitly, like a retake)
  function elevenRun(queueIn, opts) {
    if (elState.run && elState.run.running) return;
    opts = opts || {};
    var run = elState.run = { running: true, stop: false, msg: "", bad: false, cur: "", finished: 0, sent: 0, baseUsed: null };
    var queue = (queueIn || elevenUnits(elState.vk)).filter(function (u) { return elevenUnitsReady[u.vk + "|" + u.sc.id + "|" + u.role] !== u.sig; });
    function say(key, vars, bad) { run.msg = t(key, vars); run.bad = !!bad; renderEleven(); }
    function wait(ms) { return new Promise(function (ok) { setTimeout(ok, ms); }); }
    function have(items) {
      var out = [], i = 0;
      function next() {
        if (i >= items.length) return Promise.resolve(out);
        var chunk = items.slice(i, i + 150); i += 150;
        return elCall({ action: "eleven_have", items: chunk }).then(function (d) { out = out.concat(d.have || []); return next(); });
      }
      return next();
    }
    function makeOne(it, tries) {
      var body = { text: it.text, voice: it.voice, tag: it.tag, take: it.take, gen: true };
      if (it.lang) body.lang = it.lang;
      return elCall(body).then(function (d) {
        if (d.stored === false) throw new Error("not_stored: " + (d.store_error || ""));
        return d.chars || elevenSpoken(it.text, it.tag).length;
      }, function (e) {
        if (tries >= 1 || e.code === "eleven_quota" || run.stop) throw e;
        return wait(1500).then(function () { return makeOne(it, tries + 1); });
      });
    }
    function doUnit(u) {
      var name = elevenUnitName(u);
      run.cur = u.sc.id + "|" + u.role;
      say("el_checking", { unit: name });
      var vk = u.vk;
      var items = u.texts.map(function (tx) { var it = { text: tx, tag: u.tag, take: elevenTakeOf(vk, u.tag, tx), voice: "eleven:" + vk }; if (u.lang === "en") it.lang = "en"; return it; });
      return have(items).then(function (h) {
        var missing = items.filter(function (it, i) { return !h[i]; });
        var need = 0;
        missing.forEach(function (it) { need += elevenSpoken(it.text, it.tag).length; });
        return elCall({ action: "eleven_status" }).then(function (stt) {
          elState.status = stt;
          // credits used ÷ characters sent so far in this run (once it's
          // enough to say: ElevenLabs' counter can lag a moment)
          if (run.baseUsed === null) run.baseUsed = stt.used;
          else if (run.sent >= 1000) { var r = (stt.used - run.baseUsed) / run.sent; if (r >= 0.05 && r <= 3) elSetRate(r); }
          var left = opts.reserve ? Math.max(0, (Number(stt.limit) || 0) - (Number(stt.used) || 0)) : elLeftOf(stt);
          var needChars = need;
          // (if the rate is a little off and the credits run out mid-role,
          // the lines made so far are kept and not paid for again)
          need = elCredits(needChars);
          if (need > left) { run.stop = true; run.end = "low"; say("el_low", { unit: name, need: progNum(need), left: progNum(left), date: elDate(stt && stt.reset_unix) }); return false; }
          var done = items.length - missing.length, spent = 0, k = 0, failed = null;
          function worker() {
            if (failed || run.stop || k >= missing.length) return Promise.resolve();
            var it = missing[k++];
            return makeOne(it, 0).then(function (c) {
              spent += c; done++; run.sent += c;
              say("el_progress", { unit: name, done: progNum(done), total: progNum(items.length), spent: progNum(spent) });
              return worker();
            }, function (e) { failed = e; });
          }
          return Promise.all([worker(), worker(), worker()]).then(function () {
            if (failed) throw failed;
            if (run.stop) return false;
            return elCall({ action: "eleven_unit_done", voice: vk, scene: u.sc.id, role: u.role, sig: u.sig, tag: u.tag, clips: items.length, chars: u.chars }).then(function () {
              elevenUnitsReady[vk + "|" + u.sc.id + "|" + u.role] = u.sig;
              run.finished++;
              return true;
            });
          });
        });
      }).catch(function (e) {
        run.stop = true; run.end = "fail";
        say(e && e.code === "voices_sql_missing" ? "el_sql" : e && e.code === "voices_sql_tag" ? "el_sql_tag" : "el_fail", { unit: name, msg: (e && e.message) || "" }, true);
        return false;
      });
    }
    var i = 0;
    function loop() {
      if (run.stop || i >= queue.length) return Promise.resolve();
      return doUnit(queue[i++]).then(function (ok) { if (!ok) return; return loop(); });
    }
    renderEleven();
    return loop().then(function () {
      run.running = false; run.cur = "";
      // one last reading for the rate
      if (run.sent >= 1000 && run.baseUsed !== null) return elCall({ action: "eleven_status" }).then(function (stt) { var r = (stt.used - run.baseUsed) / run.sent; if (r >= 0.05 && r <= 3) elSetRate(r); }, function () {}).then(finish);
      return finish();
    });
    function finish() {
      if (!run.end) { run.end = run.stop ? "stopped" : "done"; run.bad = false; run.msg = run.end === "done" ? t("el_done", { n: progNum(run.finished) }) : t("el_stopped"); }
      return refreshEleven();
    }
  }

  function renderR2() {
    var box = el.usageR2;
    if (!box) return;
    box.textContent = "";
    var sec = usageSection(t("r2_title"));
    if (!r2State.loaded) { sec.appendChild(uNode("p", "usage-note", t("r2_loading"))); box.appendChild(sec); return; }
    if (!r2State.configured) { sec.appendChild(uNode("p", "usage-note", t("r2_off"))); box.appendChild(sec); return; }
    if (r2State.error) sec.appendChild(uNode("p", "usage-problem", t("r2_error", { msg: r2State.error })));
    else {
      var freeMb = R2_FREE_BYTES / 1048576;
      sec.appendChild(usageMeter(t("r2_meter"), t("usage_of_mb", { used: usageMb(r2State.bytes), free: progNum(freeMb) }), r2State.bytes, R2_FREE_BYTES, {}));
      sec.appendChild(uNode("p", "usage-note", t("r2_count", { n: progNum(r2State.files) })));
      if (r2State.partial) sec.appendChild(uNode("p", "usage-note", t("r2_partial")));
    }
    var left = r2SupabaseLeft();
    if (left) sec.appendChild(uNode("p", "usage-note", left.n > 0 ? t("r2_left", { n: progNum(left.n), mb: usageMb(left.bytes) }) : t("r2_none_left")));
    var busy = r2State.busy;
    if (left && (left.n > 0 || busy)) {
      var actions = uNode("div", "form-actions r2-actions");
      var copy = uNode("button", "btn-secondary", busy === "copy" ? t("r2_stop") : t("r2_copy"));
      copy.type = "button"; copy.id = "r2-copy";
      copy.disabled = busy === "purge";
      copy.addEventListener("click", function () { if (r2State.busy === "copy") { r2State.stop = true; copy.disabled = true; } else r2Run("copy"); });
      actions.appendChild(copy);
      var purge = uNode("button", "btn-secondary", busy === "purge" ? t("r2_stop") : t("r2_purge"));
      purge.type = "button"; purge.id = "r2-purge";
      purge.disabled = busy === "copy" || !!r2State.error;
      purge.addEventListener("click", function () {
        if (r2State.busy === "purge") { r2State.stop = true; purge.disabled = true; return; }
        if (!window.confirm(t("r2_purge_confirm"))) return;
        r2Run("purge");
      });
      actions.appendChild(purge);
      sec.appendChild(actions);
    }
    var tl = r2State.tally;
    if (tl && busy === "copy") sec.appendChild(uNode("p", "warm-progress", t("r2_copying", { seen: progNum(tl.seen), copied: progNum(tl.copied), skipped: progNum(tl.skipped), failed: progNum(tl.failed) })));
    if (tl && busy === "purge") sec.appendChild(uNode("p", "warm-progress", t("r2_purging", { deleted: progNum(tl.deleted), kept: progNum(tl.kept) })));
    if (!busy && r2State.msg) sec.appendChild(uNode("p", "warm-progress", r2State.msg));
    if (tl && tl.firstErr && (busy === "copy" || r2State.msg)) sec.appendChild(uNode("p", "usage-problem", t("r2_first_error", { msg: tl.firstErr })));
    box.appendChild(sec);
  }

  function startWarm() {
    if (!warmPlan || (warmRun && warmRun.running)) return;
    var voices = warmVoiceList(), jobs = [];
    warmPlan.sets.forEach(function (s) {
      if (!warmPicked[s.key]) return;
      if (s.pairs) { s.pairs.forEach(function (pr) { if (voices.indexOf(pr.voice) !== -1) jobs.push({ text: pr.text, voice: pr.voice }); }); return; }
      voices.forEach(function (voice) { s.texts.forEach(function (text) { jobs.push({ text: text, voice: voice }); }); });
    });
    if (!jobs.length) return;
    var run = warmRun = { total: jobs.length, done: 0, hit: 0, miss: 0, error: 0, fails: 0, stop: false, running: true, stopped: false, lastError: "" };
    warmTtsCacheRunning = true;
    var next = 0, paint = 0;
    function repaint(force) { var now = Date.now(); if (force || now - paint > 400) { paint = now; renderWarm(); } }
    function worker() {
      if (run.stop || next >= jobs.length) return Promise.resolve();
      var job = jobs[next++];
      return supabaseClient.functions.invoke("tts", { body: { text: job.text, voice: job.voice } }).then(function (res) {
        if (res.error || !res.data || !res.data.url) {
          // the function's own answer says what Azure said (status + detail)
          var ctx = res.error && res.error.context, st = ctx && ctx.status;
          var body = ctx && typeof ctx.json === "function" ? Promise.resolve(ctx.clone ? ctx.clone().json() : ctx.json()).catch(function () { return null; }) : Promise.resolve(null);
          return body.then(function (b) {
            var bits = [st ? "HTTP " + st : ((res.error && res.error.message) || "no_url")];
            if (b && b.error) bits.push(b.error);
            if (b && b.status) bits.push("Azure " + b.status);
            if (b && b.detail) bits.push(String(b.detail).slice(0, 160));
            throw new Error(bits.join(" · "));
          });
        }
        // made, but nowhere to put it: more would only be paid for and lost
        if (res.data.stored === false) { run.error++; run.stop = true; run.lastError = t("warm_not_stored", { msg: res.data.store_error || "" }); return; }
        // a new clip made on the free resource would use up the free month
        if (!res.data.cached && !res.data.paid) { run.miss++; run.stop = true; run.lastError = t("warm_not_paid"); return; }
        if (res.data.cached) run.hit++; else run.miss++;
        run.fails = 0;
        // remembered on this device too, so these play without asking again
        ttsUrlMemo[job.voice + "\u0000" + job.text] = res.data.url;
      }).catch(function (e) {
        run.error++; run.fails++;
        run.lastError = t("warm_error", { text: job.text, msg: (e && e.message) || "" });
        if (run.fails >= 12) run.stop = true; // something is wrong (key, quota): don't keep hammering
      }).then(function () {
        run.done++;
        repaint(false);
        return worker();
      });
    }
    var ws = [];
    for (var i = 0; i < WARM_CONCURRENCY; i++) ws.push(worker());
    renderWarm();
    Promise.all(ws).then(function () {
      run.running = false;
      run.stopped = run.stop && run.done < run.total;
      warmTtsCacheRunning = false;
      saveTtsUrlMemo();
      console.log("[warm] " + run.done + "/" + run.total + " — " + run.miss + " made, " + run.hit + " already there, " + run.error + " errors");
      repaint(true);
    });
  }

  // Account menu (2026-09-25) — the kebab trigger opposite the "voseá"
  // wordmark that replaced the old always-visible email/settings/logout
  // row. Unlike the app's modals (settings, list filter, etc.), which sit
  // behind a full-screen dim .modal-overlay and only close via an explicit
  // button, this is a small popover with nothing behind it — so it also
  // needs to close on an outside click, which is new for this codebase.
  function closeAcctMenu() {
    el.acctMenu.hidden = true;
    el.acctTrigger.setAttribute("aria-expanded", "false");
  }

  function toggleAcctMenu(evt) {
    evt.stopPropagation();
    var willOpen = el.acctMenu.hidden;
    closeAcctMenu();
    if (el.qaMenu && !el.qaMenu.hidden) closeQuickAdd();
    if (willOpen) {
      el.acctMenu.hidden = false;
      el.acctTrigger.setAttribute("aria-expanded", "true");
    }
  }

  // Re-paints everything that was already rendered before the language
  // changed. applyI18n() covers static markup on its own, but anything
  // built dynamically in JS (badges, empty states, the flashcard setup
  // screen, whichever detail view is open) has its old-language text
  // baked into already-created DOM nodes and has to be rebuilt.
  function refreshAllTranslatedViews() {
    applyGrammarLabels();
    applyI18n();
    if (el.usageOverlay && !el.usageOverlay.hidden) { renderUsage(); renderWarm(); renderR2(); renderEleven(); }
    if (escVoicePick && !el.escVoiceOverlay.hidden) renderEscVoicePicker();
    refreshListFilterUI();
    renderList();
    renderWordList();
    renderPhraseList();
    renderListsPanel();
    renderOfflineBanner();
    if (selectedId) selectVerb(selectedId);
    if (selectedWordId) selectWord(selectedWordId);
    renderTopicList();
    if (selectedTopicId) selectTopic(selectedTopicId, true);
    if (selectedListId && !el.listDetail.hidden) selectListRow(selectedListId);
    if (currentShareList) renderSharePreview();
    if (!el.flashcardsPanel.hidden) renderFlashSetup();
    if (!el.flashOverlay.hidden) renderFlashCard();
    renderLangButtons();
    refreshPracticeViews();
  }

  function setLang(lang) {
    if ((lang !== "en" && lang !== "es") || lang === currentLang) return;
    currentLang = lang;
    try { localStorage.setItem(LANG_LOCAL_KEY, lang); } catch (e) {}
    refreshAllTranslatedViews();
    pushLangChanged();
    if (currentUser) {
      supabaseClient.from("user_settings")
        .upsert({ user_id: currentUser.id, lang: lang, updated_at: new Date().toISOString() }, { onConflict: "user_id" })
        .then(function (res) {
          if (res.error) el.settingsMsg.textContent = t("msg_error_guardar", { msg: res.error.message });
        });
    }
  }

  // Called right after login. The device-level localStorage guess (already
  // applied at startup, before we know who's logged in) avoids a flash of
  // the wrong language; this corrects it to the account's real, synced
  // preference once it's back from Supabase. A first-ever login has no row
  // yet (maybeSingle() returns null rather than erroring), which just
  // means the default ('en', see LANG_LOCAL_KEY above and schema.sql's
  // user_settings.lang column — 2026-09-26, mason's ask) stands until the
  // person picks something in settings.
  function loadUserSettings() {
    if (!currentUser) return Promise.resolve();
    loadSpeechDiagSetting();
    loadPlayGoal();
    return supabaseClient.from("user_settings").select("lang, tts_voice").eq("user_id", currentUser.id).maybeSingle().then(function (res) {
      if (res.error) return;
      var lang = (res.data && res.data.lang) || "en";
      if (lang !== currentLang) {
        currentLang = lang;
        try { localStorage.setItem(LANG_LOCAL_KEY, lang); } catch (e) {}
        refreshAllTranslatedViews();
      } else {
        renderLangButtons();
      }
      var voice = (res.data && res.data.tts_voice) || "elena";
      if (voice !== ttsVoiceKey) {
        ttsVoiceKey = voice;
        try { localStorage.setItem(TTS_VOICE_LOCAL_KEY, voice); } catch (e) {}
      }
      renderVoiceButtons();
    });
  }

  // ================= conjugation model (unchanged from the original tool) =================
  var PERSONS = [
    { key: "yo", label: "yo" },
    { key: "vos", label: "vos" },
    { key: "el", label: "él / ella / ud." },
    { key: "nosotros", label: "nosotros" },
    { key: "ellos", label: "ellos / ellas / uds." }
  ];
  var TENSES = [
    { key: "presente", label: "Presente" },
    { key: "preterito", label: "Pretérito" },
    { key: "imperfecto", label: "Imperfecto" },
    { key: "futuro", label: "Futuro" },
    { key: "condicional", label: "Condicional" }
  ];
  var SUBJ_KEY = "subjPresente";
  var SUBJ_PAST_KEY = "subjPasado";
  var SUBJ_TENSES = [
    { key: SUBJ_KEY, label: "Presente" },
    { key: SUBJ_PAST_KEY, label: "Pasado" }
  ];
  var IMPERATIVE_PERSONS = [
    { key: "vos", label: "vos" },
    { key: "usted", label: "usted" },
    { key: "nosotros", label: "nosotros" },
    { key: "ustedes", label: "ustedes" }
  ];
  var REFLEXIVE_PRONOUNS = { yo: "me", vos: "te", el: "se", nosotros: "nos", ellos: "se" };

  // "Tipo gustar" verbs (gustar, doler, encantar, ...) are grammatically
  // regular but almost never used with the person as the grammatical
  // subject ("yo gusto" is real but rare). In everyday use the thing
  // liked/affected is the subject and the person is a dative object
  // pronoun: "me gusta el café" / "me gustan los perros." So instead of
  // showing each person's own (misleading) conjugated form, each row is
  // relabeled with its dative pronoun/phrase and shows the SAME invariant
  // singular/plural pair, taken from the stored él/ellos forms.
  var GUSTAR_LIKE_PERSON = {
    yo: { pronoun: "me", label: "a mí" },
    vos: { pronoun: "te", label: "a vos" },
    el: { pronoun: "le", label: "a él, ella, ud." },
    nosotros: { pronoun: "nos", label: "a nosotros" },
    ellos: { pronoun: "les", label: "a ellos, ellas, uds." }
  };

  // ================= flashcards =================
  // "Personal" tenses/moods are the ones keyed by the 5-person PERSONS grid
  // (presente..subjPasado). imperativo is a 6th matrix column (it has no
  // "yo" slot). gerundio/participio don't fit the person grid at all — no
  // person distinguishes them — so they're separate standalone toggles.
  var FLASH_PERSONAL_TENSES = TENSES.concat(SUBJ_TENSES);
  var FLASH_MATRIX_COLUMNS = FLASH_PERSONAL_TENSES.concat([{ key: "imperativo", label: "Imperativo" }]);
  // imperativo only has 4 slots (no "yo"); map the same 5-person grid
  // onto them the way the conjugation table already does — el's imperativo
  // is really usted's command, ellos's is really ustedes's.
  var IMPERATIVO_FORM_KEY = { vos: "vos", el: "usted", nosotros: "nosotros", ellos: "ustedes" };
  var IMPERATIVO_DISPLAY = { vos: "vos", el: "usted", nosotros: "nosotros", ellos: "ustedes" };

  // Mutates the shared TENSES/SUBJ_TENSES/FLASH_MATRIX_COLUMNS objects'
  // .label in place (their .key never changes, so every lookup/data
  // access that depends on .key is unaffected). Because FLASH_MATRIX_
  // COLUMNS was built with .concat() — which copies array slots, not the
  // objects themselves — the TENSES/SUBJ_TENSES entries inside it are the
  // very same objects, so one pass over each array is enough for every
  // table, flashcard prompt, etc. that reads .label to pick up the change.
  function applyGrammarLabels() {
    var dict = TENSE_LABELS[currentLang] || TENSE_LABELS.es;
    TENSES.forEach(function (x) { if (dict[x.key]) x.label = dict[x.key]; });
    SUBJ_TENSES.forEach(function (x) { if (dict[x.key]) x.label = dict[x.key]; });
    FLASH_MATRIX_COLUMNS.forEach(function (x) { if (dict[x.key]) x.label = dict[x.key]; });
  }

  function flashCellKey(tenseKey, personKey) { return tenseKey + "|" + personKey; }
  function flashCellSelectable(tenseKey, personKey) { return !(tenseKey === "imperativo" && personKey === "yo"); }
  function flashColumnCellKeys(tenseKey) {
    return PERSONS.filter(function (p) { return flashCellSelectable(tenseKey, p.key); })
      .map(function (p) { return flashCellKey(tenseKey, p.key); });
  }
  function flashRowCellKeys(personKey) {
    return FLASH_MATRIX_COLUMNS.filter(function (col) { return flashCellSelectable(col.key, personKey); })
      .map(function (col) { return flashCellKey(col.key, personKey); });
  }
