      practiceNoteSent(batch);
      practiceQueue = practiceQueue.filter(function (r) { return !sent[r.id]; });
      savePracticeQueue();
      if (practiceQueue.some(function (r) { return r.user_id === currentUser.id; })) practiceFlush();
