    try { pwa = !!((window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) || navigator.standalone); } catch (e) {}
    speechDeviceCache = {
      label: os + " · " + br + (pwa ? " · app" : ""),
      os: os, browser: br, pwa: pwa, kind: practiceDevice(),
      ua: ua.slice(0, 300)
    };
