  var DELETREAR = ["hola", "calle", "queso", "vaso", "llave", "jugo", "zapato", "año", "hielo", "kiosco", "taxi", "boca",
    "Palermo", "Belgrano", "Recoleta", "subte", "yerba", "cerveza", "guitarra", "Juan"];
