  COL_SEGS.forEach(function (k) { el["colSeg_" + k].addEventListener("click", function () { setMainTab(k); try { window.scrollTo({ top: 0 }); } catch (e) {} }); });
  el.colBarBtn.addEventListener("click", function () { openDeckBuilder(); });
